import { createTranslationAdapter } from "./api-translation.ts";
import { loadDemoI18n, renderDemoI18n } from "./demo-i18n.ts";
import { TranslationMemory, keyFor, translateUnits } from "./translation-memory.ts";

const MISSING = [
  "close-button",
  "img",
  "number-input",
  "progress",
  "rating",
  "spinner",
  "text-input",
